( sram_alloc_with_lsl ) ; static int _sram_proc_show ( struct seq_file * m , const char * desc , struct sram_piece * pfree_head , struct sram_piece * pused_head ) { struct sram_piece * pslot ; seq_printf ( m , "--- SRAM %-14s Size   PID State     \n" , desc ) ; pslot = pused_head -> next ; while ( pslot != NULL ) { seq_printf ( m , "%p-%p %10i %5i %-10s\n" , pslot -> paddr , pslot -> paddr + pslot -> size , pslot -> size , pslot -> pid , "ALLOCATED" ) ; pslot = pslot -> next ; } pslot = pfree_head -> next ; while ( pslot != NULL ) { seq_printf ( m , "%p-%p %10i %5i %-10s\n" , pslot -> paddr , pslot -> paddr + pslot -> size , pslot -> size , pslot -> pid , "FREE" ) ; pslot = pslot -> next ; } return 0 ; } 